              window.parent.postMessage({
                source: 'iframe-console',
                type: type,
                args: Array.from(args).map(arg => {
                  if (typeof arg === 'object') {
                    try { return JSON.stringify(arg); } catch(e) { return String(arg); }
                  }
                  return String(arg);
                })
              }, '*');
